```js
// app.js
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');
const argon2 = require('argon2');

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET not set');

const app = express();
app.set('trust proxy', 1); // exactly one reverse proxy in front; remove if none
app.use(express.json({ limit: '10kb' }));

app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 2 * 60 * 60 * 1000,
  },
}));

// Demo user store; replace with a DB.
const users = new Map(); // username -> { id, username, hash }
let nextId = 1;

// Verified against when the user does not exist, so response time does not reveal valid usernames.
const dummyHash = argon2.hash('dummy-password');

// Only failed responses (status >= 400) count toward the limits.
const WINDOW_MS = 15 * 60 * 1000;
const tooMany = { error: 'Too many failed attempts. Try again later.' };

const ipLimiter = rateLimit({
  windowMs: WINDOW_MS,
  limit: 20,
  skipSuccessfulRequests: true,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: tooMany,
});

const usernameLimiter = rateLimit({
  windowMs: WINDOW_MS,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  keyGenerator: (req) => `user:${String(req.body?.username ?? '').toLowerCase()}`,
  message: tooMany,
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

app.post('/register', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' ||
      !username.trim() || password.length < 8) {
    return res.status(400).json({ error: 'Invalid username or password (min 8 chars)' });
  }
  const key = username.trim().toLowerCase();
  if (users.has(key)) return res.status(409).json({ error: 'Username taken' });

  const hash = await argon2.hash(password, { type: argon2.argon2id });
  users.set(key, { id: nextId++, username: key, hash });
  res.status(201).json({ ok: true });
});

app.post('/login', ipLimiter, usernameLimiter, async (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const user = users.get(username.trim().toLowerCase());
  const ok = await argon2.verify(user ? user.hash : await dummyHash, password);
  if (!user || !ok) return res.status(401).json({ error: 'Invalid credentials' });

  // New session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.json({ ok: true });
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ userId: req.session.userId });
});

app.listen(process.env.PORT || 3000);
```

Limits: 5 failures per username and 20 per IP, per 15 minutes. Successful logins do not count.

Before production:

- **Stores:** Sessions and rate-limit counters live in process memory here. They reset on restart and are not shared across instances. Use a shared store such as Redis for both (`connect-redis`, `rate-limit-redis`).
- **Username lockout:** The per-username limit lets anyone lock a known account out for 15 minutes by sending 5 bad passwords. Dropping it removes that, but then a distributed attack on one account is only limited per IP.
- **`trust proxy`:** Must match your real proxy count. Too low and every client shares the proxy's IP; too high and clients can spoof `X-Forwarded-For` to dodge the IP limit.
- **HTTPS:** The cookie is `secure` only when `NODE_ENV=production`, so production must serve over HTTPS.
